-- Operational ownership is not a bypass of an inactive resource audience.
CREATE FUNCTION phase10_catalog_target_current(s TEXT,scope TEXT,section_id TEXT,class_id TEXT,student_id TEXT) RETURNS BOOLEAN AS $$
 SELECT EXISTS(SELECT 1 FROM "School" WHERE "id"=s AND "isActive") AND (
 scope='SCHOOL' OR (scope='SECTION' AND EXISTS(SELECT 1 FROM "SchoolSection" WHERE "schoolId"=s AND "id"=section_id AND "isActive")) OR (scope='CLASS' AND EXISTS(SELECT 1 FROM "SchoolClass" c JOIN "SchoolSection" section ON section."schoolId"=c."schoolId" AND section."id"=c."sectionId" AND section."isActive" WHERE c."schoolId"=s AND c."id"=class_id AND c."isActive")) OR (scope='STUDENT' AND EXISTS(SELECT 1 FROM "StudentRecord" p JOIN "StudentEnrollment" e ON e."schoolId"=p."schoolId" AND e."studentId"=p."id" AND e."status"='ACTIVE' JOIN "AcademicSession" session ON session."schoolId"=e."schoolId" AND session."id"=e."sessionId" AND session."status"='ACTIVE' JOIN "SchoolClass" c ON c."schoolId"=e."schoolId" AND c."id"=e."classId" AND c."isActive" JOIN "SchoolSection" section ON section."schoolId"=c."schoolId" AND section."id"=c."sectionId" AND section."isActive" WHERE p."schoolId"=s AND p."id"=student_id AND p."status"='ENROLLED')));
$$ LANGUAGE sql STABLE;
CREATE OR REPLACE FUNCTION can_read_library_catalog(s TEXT,r UUID,u TEXT) RETURNS BOOLEAN AS $$
 SELECT EXISTS(SELECT 1 FROM "LibraryCatalogRelease" release JOIN "LibraryCatalogEntry" c ON c."schoolId"=release."schoolId" AND c."id"=release."entryId"
 WHERE release."schoolId"=s AND release."id"=r AND phase10_catalog_curator(s,c."curatorUserId",c."curatorMembershipId") AND phase10_catalog_target_current(s,release."scope",release."sectionId",release."classId",release."studentId")
 AND phase10_owner(s,release."actorUserId")
 AND EXISTS(SELECT 1 FROM "LibraryCatalogReview" review WHERE review."schoolId"=s AND review."entryId"=c."id" AND review."revision"=release."revision" AND review."action"='APPROVE' AND phase10_owner(s,review."actorUserId"))
 AND NOT EXISTS(SELECT 1 FROM "LibraryCatalogWithdrawal" w WHERE w."schoolId"=s AND w."releaseId"=release."id")
 AND NOT EXISTS(SELECT 1 FROM "LibraryCatalogRelease" newer WHERE newer."schoolId"=s AND newer."entryId"=c."id" AND newer."ordinal">release."ordinal")
 AND (u=c."curatorUserId" OR phase10_catalog_staff_scope(s,release."scope",release."sectionId",release."classId",release."studentId",u) OR EXISTS(SELECT 1 FROM "Membership" m JOIN "StudentAccountLink" b ON b."schoolId"=s AND b."studentMembershipId"=m."id" JOIN "StudentRecord" p ON p."schoolId"=s AND p."id"=b."studentId" AND p."status"='ENROLLED' JOIN "StudentEnrollment" e ON e."schoolId"=s AND e."studentId"=p."id" AND e."status"='ACTIVE' JOIN "AcademicSession" session ON session."schoolId"=s AND session."id"=e."sessionId" AND session."status"='ACTIVE' JOIN "SchoolClass" room ON room."schoolId"=s AND room."id"=e."classId" AND room."isActive" JOIN "SchoolSection" section ON section."schoolId"=s AND section."id"=room."sectionId" AND section."isActive" WHERE m."schoolId"=s AND m."userId"=u AND m."isActive" AND m."role"='STUDENT' AND NOT EXISTS(SELECT 1 FROM "StudentAccountLinkRevocation" v WHERE v."schoolId"=s AND v."linkId"=b."id") AND (release."scope"='SCHOOL' OR release."sectionId"=section."id" OR release."classId"=room."id" OR release."studentId"=p."id"))));
$$ LANGUAGE sql STABLE;
